package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, t int
	fmt.Fscan(in, &n, &t)

	// dp[lastY][direction][peaks][valleys]
	// direction: 0 = descending, 1 = ascending
	dp := [5][2][11][11]int64{}

	for y1 := 1; y1 <= 4; y1++ {
		for y2 := 1; y2 <= 4; y2++ {
			if y1 == y2 {
				continue
			}
			dir := 0
			if y2 > y1 {
				dir = 1
			}
			dp[y2][dir][0][0]++
		}
	}

	for pos := 3; pos <= n; pos++ {
		next := [5][2][11][11]int64{}

		for last := 1; last <= 4; last++ {
			for prevDir := 0; prevDir < 2; prevDir++ {
				for peaks := 0; peaks <= t; peaks++ {
					for valleys := 0; valleys <= t-1; valleys++ {
						count := dp[last][prevDir][peaks][valleys]
						if count == 0 {
							continue
						}

						for y := 1; y <= 4; y++ {
							if y == last {
								continue
							}

							dir := 0
							if y > last {
								dir = 1
							}

							newPeaks, newValleys := peaks, valleys
							if prevDir == 1 && dir == 0 {
								newPeaks++
							} else if prevDir == 0 && dir == 1 {
								newValleys++
							}

							if newPeaks <= t && newValleys <= t-1 {
								next[y][dir][newPeaks][newValleys] += count
							}
						}
					}
				}
			}
		}

		dp = next
	}

	var answer int64
	for last := 1; last <= 4; last++ {
		for dir := 0; dir < 2; dir++ {
			answer += dp[last][dir][t][t-1]
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}

