func main() {
	in := bufio.NewReader(os.Stdin)

	var n, t int
	fmt.Fscan(in, &n, &t)

	var dp [5][3][11][11]int64
	for y := 1; y <= 4; y++ {
		dp[y][0][0][0] = 1
	}

	for i := 1; i < n; i++ {
		var next [5][3][11][11]int64

		for last := 1; last <= 4; last++ {
			for dir := 0; dir <= 2; dir++ {
				for peaks := 0; peaks <= t; peaks++ {
