								continue
							}

							newDir := 1
							if y < last {
								newDir = 2
							}

							newPeaks, newValleys := peaks, valleys
							if dir == 1 && newDir == 2 {
								newPeaks++
							} else if dir == 2 && newDir == 1 {
								newValleys++
							}

							if newPeaks <= t && newValleys <= t-1 {
								next[y][newDir][newPeaks][newValleys] += count
							}
						}
					}
				}
			}
		}

		dp = next
	}

	var answer int64
	for y := 1; y <= 4; y++ {
		for dir := 1; dir <= 2; dir++ {
